import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true); setError('');
    try {
      await login(form.email, form.password);
      toast.success('Bienvenue !');
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur de connexion');
    } finally {
      setLoading(false);
    }
  };

  const demoLogins = [
    { label: 'Administrateur', email: 'admin@lhm-madagascar.org', pwd: 'Admin@1234' },
    { label: 'Direction', email: 'direction@lhm-madagascar.org', pwd: 'Direction@1234' },
    { label: 'Assistant RH', email: 'rh@lhm-madagascar.org', pwd: 'RH@1234' },
    { label: 'Stock', email: 'stock@lhm-madagascar.org', pwd: 'Stock@1234' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', background: 'linear-gradient(135deg, #091628 0%, #0f2044 50%, #1a3560 100%)' }}>
      {/* Left panel */}
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', padding: '40px 60px', color: 'white' }}>
        <div style={{ maxWidth: 460 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 48 }}>
            <div style={{ width: 56, height: 56, background: 'linear-gradient(135deg, #a07830, #c9a84c)', borderRadius: 16, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.6rem', boxShadow: '0 8px 24px rgba(201,168,76,0.4)' }}>✝</div>
            <div>
              <h1 style={{ fontFamily: "'Playfair Display', serif", fontSize: '1.5rem', fontWeight: 700, lineHeight: 1.2 }}>LHM Madagascar</h1>
              <p style={{ color: '#c9a84c', fontSize: '0.85rem', marginTop: 2 }}>Feon'ny Filazantsara</p>
            </div>
          </div>

          <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: '2.4rem', fontWeight: 700, lineHeight: 1.2, marginBottom: 16 }}>
            Système de Gestion<br />
            <span style={{ color: '#c9a84c' }}>Intégrée</span>
          </h2>
          <p style={{ color: 'rgba(255,255,255,0.65)', lineHeight: 1.7, fontSize: '0.95rem', marginBottom: 48 }}>
            Plateforme centralisée pour la gestion du personnel, des volontaires, des stocks et des projets de l'organisation.
          </p>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            {['👥 Personnel', '🤝 Volontaires', '📦 Stock', '🎯 Projets'].map(item => (
              <div key={item} style={{ background: 'rgba(255,255,255,0.07)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, padding: '12px 16px', fontSize: '0.85rem', color: 'rgba(255,255,255,0.8)' }}>
                {item}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Right panel - form */}
      <div style={{ width: 460, background: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px' }}>
        <div style={{ width: '100%', maxWidth: 380 }}>
          <h3 style={{ fontFamily: "'Playfair Display', serif", fontSize: '1.6rem', color: 'var(--navy)', marginBottom: 8 }}>Connexion</h3>
          <p style={{ color: 'var(--gray-500)', fontSize: '0.88rem', marginBottom: 32 }}>Entrez vos identifiants pour accéder au système.</p>

          {error && (
            <div style={{ background: '#fee2e2', border: '1px solid #fca5a5', borderRadius: 9, padding: '12px 16px', color: '#991b1b', fontSize: '0.85rem', marginBottom: 20 }}>
              ⚠️ {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div style={{ marginBottom: 18 }}>
              <label>Adresse email</label>
              <input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="votre@email.com" required />
            </div>
            <div style={{ marginBottom: 24 }}>
              <label>Mot de passe</label>
              <input type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} placeholder="••••••••" required />
            </div>
            <button type="submit" disabled={loading} style={{ width: '100%', background: 'linear-gradient(135deg, var(--navy), var(--navy-light))', color: 'white', border: 'none', borderRadius: 10, padding: '13px', fontSize: '0.95rem', fontWeight: 600, cursor: loading ? 'not-allowed' : 'pointer', opacity: loading ? 0.8 : 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
              {loading ? <><div style={{ width: 18, height: 18, border: '2px solid rgba(255,255,255,0.3)', borderTop: '2px solid white', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} /> Connexion...</> : '🔑 Se connecter'}
            </button>
          </form>

          <div style={{ marginTop: 28, padding: '16px', background: 'var(--gray-50)', borderRadius: 10, border: '1px solid var(--gray-200)' }}>
            <p style={{ fontSize: '0.75rem', color: 'var(--gray-500)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 10 }}>Comptes de démonstration</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {demoLogins.map(d => (
                <button key={d.label} type="button" onClick={() => setForm({ email: d.email, password: d.pwd })}
                  style={{ background: 'white', border: '1px solid var(--gray-200)', borderRadius: 7, padding: '7px 12px', fontSize: '0.8rem', cursor: 'pointer', textAlign: 'left', color: 'var(--navy)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 600 }}>{d.label}</span>
                  <span style={{ color: 'var(--gray-400)', fontSize: '0.73rem' }}>{d.email}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
